// Prototype player. Reads flow.json (behaviour) and zones.json (tap zones, generated by `npm run proto`).
// Nothing here is specific to Maya's screens: change flow.json, not this file.
(async function () {
  const $ = (s) => document.querySelector(s);
  const [flow, gen] = await Promise.all([fetch('flow.json').then(r => r.json()), fetch('zones.json').then(r => r.json())]);
  const [W, H] = flow.size, S = flow.screens;
  const LS = 'maya-proto-zones-v1';
  let edits = {}; try { edits = JSON.parse(localStorage.getItem(LS) || '{}'); } catch (e) {}
  let cur = null, hist = [], timer = null, toastT = null, front = 'A', editing = false;

  document.title = flow.title;
  const zonesOf = (id) => {
    if (edits[id]) return edits[id];
    const s = S[id], z = gen[id] || {}, out = [];
    const all = [...(s.hotspots || []), ...((flow.global.except || []).includes(id) ? [] : flow.global.hotspots || [])];
    for (const h of all) if (z[h.id]) out.push({ id: h.id, label: h.label || h.id, rect: z[h.id], go: h.go, toast: h.toast });
    return out;
  };

  // scale the 1920 x 1200 stage into the available area
  function fit() { const w = $('#stagewrap'), k = Math.min(w.clientWidth / W, w.clientHeight / H), st = $('#stage');
    st.style.transform = `scale(${k})`; st.style.left = (w.clientWidth - W * k) / 2 + 'px'; st.style.top = (w.clientHeight - H * k) / 2 + 'px'; }
  addEventListener('resize', fit); fit();
  new ResizeObserver(fit).observe($('#stagewrap'));

  function toast(t) { const el = $('#toast'); el.textContent = t; el.classList.add('on'); clearTimeout(toastT); toastT = setTimeout(() => el.classList.remove('on'), 2600); }
  function clearAuto() { clearTimeout(timer); const p = $('#prog'); p.style.transition = 'none'; p.style.width = '0'; }

  function go(id, opts = {}) {
    if (id === 'back') { if (!hist.length) return; id = hist.pop(); opts.noPush = true; }
    if (!S[id]) return;
    if (cur && !opts.noPush && !opts.replace) hist.push(cur);
    show(id);
  }

  function show(id) {
    cur = id; const s = S[id]; clearAuto(); history.replaceState(null, '', '#' + id);
    // crossfade images
    const next = front === 'A' ? 'B' : 'A', ni = $('#img' + next), fi = $('#img' + front);
    ni.onload = () => { ni.style.opacity = 1; fi.style.opacity = 0; front = next; };
    ni.src = `shots/${id}.jpg`; if (ni.complete) ni.onload();
    ni.alt = `${id} ${s.title}`;
    // chrome
    $('#meta').textContent = `${s.scene ? 'Scene ' + s.scene + ' · ' : ''}${s.time} · ${id} ${s.title}`;
    $('#note').textContent = s.note || '';
    $('#maya').textContent = s.maya ? `Maya: “${s.maya}”` : '';
    $('#ctal').textContent = s.cta ? s.cta.label : '';
    $('#ctas').textContent = s.cta && s.cta.say ? `Michael: “${s.cta.say}”` : '';
    $('#cta').hidden = !s.cta;
    $('#back').disabled = !hist.length; $('#back').style.opacity = hist.length ? 1 : .35;
    const br = $('#branches'); br.innerHTML = '';
    (s.branches || []).forEach(b => { const e = document.createElement('button'); e.innerHTML = `<b>${b.tag || 'What if'}</b>${b.label}`; e.onclick = () => go(b.go); br.appendChild(e); });
    drawZones();
    if (s.auto && !editing) { const p = $('#prog'); requestAnimationFrame(() => { p.style.transition = `width ${s.auto.ms}ms linear`; p.style.width = '100%'; });
      timer = setTimeout(() => go(s.auto.go), s.auto.ms); }
  }

  function drawZones() {
    const box = $('#zones'); box.innerHTML = '';
    zonesOf(cur).forEach((z, i) => {
      const e = document.createElement('div'); e.className = 'z'; e.dataset.label = z.label; e.dataset.i = i;
      e.style.cssText = `left:${z.rect[0]}px;top:${z.rect[1]}px;width:${z.rect[2]}px;height:${z.rect[3]}px`;
      e.setAttribute('role', 'button'); e.setAttribute('aria-label', z.label); e.tabIndex = 0;
      const h = document.createElement('i'); h.className = 'h'; e.appendChild(h);
      const act = (ev) => { if (editing) return; ev.stopPropagation(); if (z.toast) toast(z.toast); if (z.go) go(z.go); };
      e.addEventListener('click', act); e.addEventListener('keydown', ev => { if (ev.key === 'Enter') act(ev); });
      box.appendChild(e);
    });
  }

  // tapping empty space shows where the live zones are
  $('#stage').addEventListener('click', (e) => { if (editing || e.target.closest('.z')) return;
    document.querySelectorAll('.z').forEach(z => { z.classList.remove('hint'); void z.offsetWidth; z.classList.add('hint'); });
    setTimeout(() => document.querySelectorAll('.z').forEach(z => z.classList.remove('hint')), 1200); });

  $('#cta').onclick = () => { const s = S[cur]; if (s.cta) go(s.cta.go); };
  $('#back').onclick = () => go('back');
  $('#restart').onclick = () => { hist = []; go(flow.start, { noPush: true }); };
  $('#taps').onclick = () => { const on = document.body.classList.toggle('taps'); $('#taps').setAttribute('aria-pressed', on); };
  $('#menu').onclick = openMenu; $('#help').onclick = () => $('#helppanel').hidden = false; $('#helpclose').onclick = () => $('#helppanel').hidden = true;
  document.querySelectorAll('aside').forEach(a => a.addEventListener('click', e => { if (e.target === a) a.hidden = true; }));

  function openMenu() {
    const l = $('#menulist'); l.innerHTML = ''; let last = null;
    const order = Object.keys(S).sort((a, b) => (S[a].scene || 99) - (S[b].scene || 99) || 0);
    for (const id of Object.keys(S)) { const s = S[id], g = s.scene ? 'Scene ' + s.scene : 'Anytime and edge cases';
      if (g !== last) { const d = document.createElement('div'); d.className = 'grp'; d.textContent = g; l.appendChild(d); last = g; }
      const b = document.createElement('button'); b.innerHTML = `<b>${id}</b><span>${s.title}</span>`; b.onclick = () => { $('#menupanel').hidden = true; hist = []; go(id, { noPush: true }); }; l.appendChild(b); }
    $('#menupanel').hidden = false;
  }

  addEventListener('keydown', (e) => {
    if (e.target.tagName === 'INPUT' || e.metaKey || e.ctrlKey) return;
    const k = e.key.toLowerCase();
    if (editing) { if ((k === 'delete' || k === 'backspace') && sel != null) { const z = editList(); z.splice(sel, 1); sel = null; saveEdit(z); } if (k === 'escape') exitEdit(); return; }
    if (k === 'arrowleft') go('back');
    else if (k === 'arrowright' || k === ' ') { e.preventDefault(); $('#cta').click(); }
    else if (k === 't') $('#taps').click();
    else if (k === 'm') openMenu();
    else if (k === 'r') $('#restart').click();
    else if (k === 'e') enterEdit();
    else if (k === 'escape') document.querySelectorAll('aside').forEach(a => a.hidden = true);
  });

  // ---- zone editor (press E or open with ?edit) -------------------------------------------------
  let sel = null;
  const editList = () => { if (!edits[cur]) edits[cur] = JSON.parse(JSON.stringify(zonesOf(cur))); return edits[cur]; };
  function saveEdit(list) { edits[cur] = list; try { localStorage.setItem(LS, JSON.stringify(edits)); } catch (e) {} drawZones(); wireEdit(); }
  function enterEdit() { editing = true; document.body.classList.add('edit'); $('#editbar').hidden = false; clearAuto(); wireEdit(); }
  function exitEdit() { editing = false; document.body.classList.remove('edit'); $('#editbar').hidden = true; drawZones(); }
  $('#exitedit').onclick = exitEdit;
  $('#resetedit').onclick = () => { delete edits[cur]; try { localStorage.setItem(LS, JSON.stringify(edits)); } catch (e) {} drawZones(); wireEdit(); };
  $('#copyjson').onclick = () => {
    const out = zonesOf(cur).map(z => { const o = { id: z.id, label: z.label, rect: z.rect }; if (z.go) o.go = z.go; if (z.toast) o.toast = z.toast; return o; });
    const txt = `"${cur}": { ... "hotspots": ${JSON.stringify(out, null, 2)} }`;
    navigator.clipboard.writeText(txt).then(() => toast('Copied. Paste into flow.json, replacing this screen’s "hotspots".'), () => prompt('Copy:', txt));
  };
  function wireEdit() {
    const scale = () => $('#stage').getBoundingClientRect().width / W;
    document.querySelectorAll('.z').forEach(el => {
      const i = +el.dataset.i;
      el.addEventListener('pointerdown', (ev) => { if (!editing) return; ev.preventDefault(); ev.stopPropagation(); sel = i;
        const list = editList(), r = list[i].rect.slice(), sx = ev.clientX, sy = ev.clientY, resize = ev.target.classList.contains('h'), k = scale();
        const mv = (m) => { const dx = (m.clientX - sx) / k, dy = (m.clientY - sy) / k;
          list[i].rect = resize ? [r[0], r[1], Math.max(40, r[2] + dx), Math.max(40, r[3] + dy)].map(Math.round) : [r[0] + dx, r[1] + dy, r[2], r[3]].map(Math.round);
          el.style.cssText = `left:${list[i].rect[0]}px;top:${list[i].rect[1]}px;width:${list[i].rect[2]}px;height:${list[i].rect[3]}px`; };
        const up = () => { removeEventListener('pointermove', mv); removeEventListener('pointerup', up); saveEdit(list); };
        addEventListener('pointermove', mv); addEventListener('pointerup', up); });
      el.addEventListener('dblclick', () => { if (!editing) return; const list = editList(); const t = prompt('Go to screen (ID, or "back"):', list[i].go || ''); if (t !== null) { list[i].go = t || undefined; saveEdit(list); } });
    });
  }
  $('#stage').addEventListener('pointerdown', (ev) => { if (!editing || !ev.altKey || ev.target.closest('.z')) return;
    const k = $('#stage').getBoundingClientRect().width / W, b = $('#stage').getBoundingClientRect();
    const x0 = (ev.clientX - b.left) / k, y0 = (ev.clientY - b.top) / k;
    const up = (m) => { removeEventListener('pointerup', up); const x1 = (m.clientX - b.left) / k, y1 = (m.clientY - b.top) / k;
      const r = [Math.min(x0, x1), Math.min(y0, y1), Math.abs(x1 - x0), Math.abs(y1 - y0)].map(Math.round); if (r[2] < 30 || r[3] < 30) return;
      const list = editList(); list.push({ id: 'new' + list.length, label: 'New zone', rect: r }); saveEdit(list); };
    addEventListener('pointerup', up); });

  addEventListener('hashchange', () => { const id = location.hash.slice(1); if (S[id] && id !== cur) { hist = []; go(id, { noPush: true }); } });
  // start
  const start = (location.hash || '').slice(1);
  go(S[start] ? start : flow.start, { noPush: true });
  if (new URLSearchParams(location.search).has('edit')) enterEdit();
})();
